'use client';

import React, { useEffect, useRef, useState } from 'react';

/**
 * ImpactReel — Horizontal scroll-driven reel
 * Pinned section where cards scroll horizontally as user scrolls vertically (GSAP ScrollTrigger pattern)
 * Pure CSS scroll-driven + JS ScrollTrigger polyfill
 */
export default function ImpactReel() {
  const sectionRef = useRef(null);
  const trackRef = useRef(null);
  const [progress, setProgress] = useState(0);

  const reelCards = [
    {
      icon: '⚡',
      metric: '<2%',
      sub: 'Error Rate',
      label: 'Flipkart Talk2Data',
      detail: 'Zero-shot NL→SQL across petabyte-scale warehouse analytics. Self-healing multi-agent loops.',
      color: '#38bdf8',
    },
    {
      icon: '🎯',
      metric: '98.4%',
      sub: 'Groundedness',
      label: 'Enterprise RAG',
      detail: 'Sub-minute document retrieval from 100+ page manuals with zero hallucination SLA.',
      color: '#10b981',
    },
    {
      icon: '🎙',
      metric: '<400ms',
      sub: 'Voice Latency',
      label: 'Multilingual Voice AI',
      detail: 'Full-duplex WebSocket pipeline. 5 concurrent channels. 100% automated scheduling.',
      color: '#f59e0b',
    },
    {
      icon: '🎬',
      metric: '80%',
      sub: 'Cycle Cut',
      label: 'AI Film Studio',
      detail: 'Script-to-screen in hours via 4-agent LangGraph DAG with visual memory anchors.',
      color: '#3b82f6',
    },
    {
      icon: '🖼',
      metric: '10×',
      sub: 'Asset Velocity',
      label: 'Creativium Engine',
      detail: 'Brand-compliant marketing assets across 12+ formats via Imagen 3 outpainting.',
      color: '#ec4899',
    },
    {
      icon: '📄',
      metric: '75%',
      sub: 'Faster Bids',
      label: 'RFP Intelligence',
      detail: '200+ page tender analysis with zero hallucinated contractual obligations.',
      color: '#8b5cf6',
    },
  ];

  useEffect(() => {
    const section = sectionRef.current;
    const track = trackRef.current;
    if (!section || !track) return;

    const handleScroll = () => {
      const rect = section.getBoundingClientRect();
      const sectionHeight = section.offsetHeight;
      const viewH = window.innerHeight;

      // Pin range: when section top hits viewport top, until we've scrolled sectionHeight
      const scrolled = -rect.top;
      const maxScroll = sectionHeight - viewH;

      if (scrolled < 0 || scrolled > maxScroll) {
        setProgress(scrolled > maxScroll ? 1 : 0);
        return;
      }

      const pct = scrolled / maxScroll;
      setProgress(pct);

      // Translate track horizontally
      const trackWidth = track.scrollWidth - track.clientWidth;
      track.style.transform = `translateX(-${pct * trackWidth}px)`;
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll();

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <section
      ref={sectionRef}
      id="impact-reel"
      style={{ height: '320vh', position: 'relative' }}
    >
      {/* Sticky wrapper */}
      <div className="reel-sticky-wrap">
        <div className="reel-header-row">
          <div className="glass-pill" style={{ marginBottom: '0' }}>
            <span className="pulse-dot" />
            <span>PRODUCTION IMPACT REEL · SCROLL TO ADVANCE →</span>
          </div>
          <div className="reel-progress-track">
            <div className="reel-progress-fill" style={{ width: `${progress * 100}%` }} />
          </div>
          <span className="reel-progress-pct">{Math.round(progress * 100)}%</span>
        </div>

        <h2 className="reel-headline">
          Six Systems.<br />
          <span className="text-glow-gradient">One Engineering Standard.</span>
        </h2>

        {/* Horizontal reel track */}
        <div className="reel-overflow-clip">
          <div ref={trackRef} className="reel-track">
            {reelCards.map((card, i) => (
              <div
                key={i}
                className="reel-card glass-panel"
                style={{
                  '--reel-color': card.color,
                  transitionDelay: `${i * 0.06}s`,
                }}
              >
                <div className="reel-card-icon">{card.icon}</div>
                <div className="reel-card-metric" style={{ color: card.color }}>
                  {card.metric}
                </div>
                <div className="reel-card-sub">{card.sub}</div>
                <div className="reel-card-label">{card.label}</div>
                <p className="reel-card-detail">{card.detail}</p>

                {/* Animated corner accent */}
                <div className="reel-corner-accent" style={{ borderColor: `${card.color}30` }} />
              </div>
            ))}
          </div>
        </div>

        <p className="reel-scroll-hint">↓ Keep scrolling to advance the reel</p>
      </div>

      <style jsx>{`
        .reel-sticky-wrap {
          position: sticky;
          top: 0;
          height: 100vh;
          display: flex;
          flex-direction: column;
          justify-content: center;
          overflow: hidden;
          padding: 0 40px;
          background: rgba(7, 9, 14, 0.92);
          z-index: 10;
        }

        .reel-header-row {
          display: flex;
          align-items: center;
          gap: 20px;
          margin-bottom: 24px;
          flex-wrap: wrap;
        }

        .reel-progress-track {
          flex: 1;
          max-width: 260px;
          height: 3px;
          border-radius: 9999px;
          background: rgba(212, 175, 55, 0.15);
          overflow: hidden;
        }

        .reel-progress-fill {
          height: 100%;
          border-radius: 9999px;
          background: linear-gradient(90deg, #b8860b, #f3e5ab, #d4af37);
          box-shadow: 0 0 10px rgba(212, 175, 55, 0.7);
          transition: width 0.12s linear;
        }

        .reel-progress-pct {
          font-family: 'JetBrains Mono', monospace;
          font-size: 0.78rem;
          font-weight: 700;
          color: #d4af37;
          min-width: 34px;
        }

        .reel-headline {
          font-size: clamp(2.2rem, 4vw, 3.4rem);
          font-weight: 850;
          line-height: 1.12;
          letter-spacing: -0.03em;
          color: #ffffff;
          margin-bottom: 36px;
        }

        .reel-overflow-clip {
          overflow: hidden;
          width: 100%;
          padding-bottom: 8px;
        }

        .reel-track {
          display: flex;
          gap: 24px;
          width: max-content;
          transition: transform 0.05s linear;
          will-change: transform;
          padding: 4px 4px 16px 4px;
        }

        .reel-card {
          width: 300px;
          flex-shrink: 0;
          padding: 32px 28px;
          display: flex;
          flex-direction: column;
          gap: 10px;
          border-radius: 22px;
          background: rgba(14, 18, 27, 0.85);
          border: 1px solid rgba(255, 255, 255, 0.09);
          position: relative;
          overflow: hidden;
          transition:
            border-color 0.25s ease,
            box-shadow 0.25s ease,
            transform 0.28s cubic-bezier(0.16, 1, 0.3, 1);
        }

        .reel-card::after {
          content: '';
          position: absolute;
          inset: 0;
          background: radial-gradient(
            circle at 20% 20%,
            var(--reel-color, #38bdf8) 0%,
            transparent 60%
          );
          opacity: 0.04;
          pointer-events: none;
        }

        .reel-card:hover {
          border-color: var(--reel-color, rgba(255,255,255,0.2));
          box-shadow: 0 20px 50px -12px rgba(0, 0, 0, 0.9),
                      0 0 30px -8px var(--reel-color, rgba(56,189,248,0.15));
          transform: translateY(-6px) scale(1.02);
        }

        .reel-corner-accent {
          position: absolute;
          top: 0;
          right: 0;
          width: 80px;
          height: 80px;
          border-top: 1px solid;
          border-right: 1px solid;
          border-top-right-radius: 22px;
          pointer-events: none;
        }

        .reel-card-icon {
          font-size: 2rem;
          line-height: 1;
          filter: drop-shadow(0 0 12px currentColor);
        }

        .reel-card-metric {
          font-family: 'JetBrains Mono', monospace;
          font-size: 2.8rem;
          font-weight: 850;
          line-height: 1;
          text-shadow: 0 0 24px currentColor;
          transition: text-shadow 0.3s ease;
        }

        .reel-card:hover .reel-card-metric {
          text-shadow: 0 0 40px currentColor;
        }

        .reel-card-sub {
          font-family: 'JetBrains Mono', monospace;
          font-size: 0.80rem;
          font-weight: 700;
          letter-spacing: 0.06em;
          text-transform: uppercase;
          color: var(--text-muted, #94a3b8);
          margin-top: -6px;
        }

        .reel-card-label {
          font-size: 1.05rem;
          font-weight: 750;
          color: #ffffff;
          margin-top: 4px;
        }

        .reel-card-detail {
          font-size: 0.90rem;
          color: var(--text-secondary, #e2e8f0);
          line-height: 1.55;
          margin: 0;
        }

        .reel-scroll-hint {
          margin-top: 22px;
          font-family: 'JetBrains Mono', monospace;
          font-size: 0.78rem;
          color: rgba(212, 175, 55, 0.6);
          letter-spacing: 0.05em;
          animation: hintBounce 2s ease-in-out infinite;
        }

        @keyframes hintBounce {
          0%, 100% { transform: translateY(0); opacity: 0.6; }
          50% { transform: translateY(4px); opacity: 1; }
        }

        @media (max-width: 768px) {
          .reel-sticky-wrap {
            padding: 0 20px;
          }
          .reel-card {
            width: 260px;
          }
          .reel-card-metric {
            font-size: 2.2rem;
          }
        }
      `}</style>
    </section>
  );
}
